// ─── File: DryDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.account;

import java.math.BigDecimal;
import java.util.logging.*;

public class DryDemo {
    private static final Logger log = Logger.getLogger(DryDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountPolicy policy = new AccountPolicy(new BigDecimal("5000"), new BigDecimal("0.02"));

        // Both services consult the SAME policy — no duplicated numbers.
        WithdrawalService withdrawal = new WithdrawalService(policy);
        MaintenanceService maintenance = new MaintenanceService(policy);

        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya", new BigDecimal("4000")); // below min

        log.info("=== DRY: one rule, consulted by many flows ===");
        withdrawal.withdraw(rajesh, new BigDecimal("990000")); // leaves 10,000 (>= min) OK
        withdrawal.withdraw(rajesh, new BigDecimal("8000"));   // would drop below min -> blocked
        maintenance.applyMonthlyFee(priya);                    // below-min fee

        // ONE change updates every flow at once.
        log.info("=== Regulator raises minimum balance to Rs.10000 (single edit) ===");
        AccountPolicy newPolicy = new AccountPolicy(new BigDecimal("10000"), new BigDecimal("0.02"));
        new MaintenanceService(newPolicy).applyMonthlyFee(rajesh);
    }
}

