class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) {
            this.accountId = id;
            this.holderName = name
            this.balance = bal;
    }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { balance = balance.subtract(amt); }
}

// ─── Would be in policy/AccountPolicy.java ───
// SINGLE SOURCE OF TRUTH for account rules. Change here = change everywhere.
class AccountPolicy {
    private final BigDecimal minBalance;
    private final BigDecimal belowMinFeeRate;
    AccountPolicy(BigDecimal minBalance, BigDecimal belowMinFeeRate) {
        this.minBalance = minBalance;
        this.belowMinFeeRate = belowMinFeeRate;
    }
    BigDecimal getMinBalance() { return minBalance; }

    boolean allowsWithdrawal(BigDecimal currentBalance, BigDecimal amount) {
        return currentBalance.subtract(amount).compareTo(minBalance) >= 0;
    }
    BigDecimal belowMinimumFee(BigDecimal balance) {
        if (balance.compareTo(minBalance) >= 0) return BigDecimal.ZERO;
        return balance.multiply(belowMinFeeRate);
    }
}

// ─── Would be in service/WithdrawalService.java ───
class WithdrawalService {
    private static final Logger log = Logger.getLogger(WithdrawalService.class.getName());
    private final AccountPolicy policy;
    WithdrawalService(AccountPolicy policy) { this.policy = policy; }

    void withdraw(Account acc, BigDecimal amount) {
        if (!policy.allowsWithdrawal(acc.getBalance(), amount)) {
            log.warning(() -> "Withdrawal Rs." + amount + " blocked for " + acc.getAccountId()
                    + " — would breach min balance Rs." + policy.getMinBalance());
            return;
        }
        acc.debit(amount);
        log.info(() -> "Withdrew Rs." + amount + " from " + acc.getAccountId()
                + " -> balance Rs." + acc.getBalance());
    }
}

// ─── Would be in service/MaintenanceService.java ───
class MaintenanceService {
    private static final Logger log = Logger.getLogger(MaintenanceService.class.getName());
    private final AccountPolicy policy;
    MaintenanceService(AccountPolicy policy) { this.policy = policy; }

    void applyMonthlyFee(Account acc) {
        BigDecimal fee = policy.belowMinimumFee(acc.getBalance());
        if (fee.compareTo(BigDecimal.ZERO) > 0) {
            acc.debit(fee);
            log.warning(() -> acc.getAccountId() + " below min balance -> fee Rs." + fee
                    + ", balance Rs." + acc.getBalance());
        } else {
            log.info(() -> acc.getAccountId() + " above min balance -> no fee");
        }
    }
}

